from typing import List, Optional
from fastapi import APIRouter, HTTPException, Query
from app.database.connection import get_db_connection

router = APIRouter(prefix="/companies", tags=["Companies"])

@router.get("")
def list_companies(search: Optional[str] = Query(None, description="Search ticker or name")):
    """List cached companies in SQLite."""
    conn = get_db_connection()
    if search:
        query = "%" + search.strip() + "%"
        rows = conn.execute(
            "SELECT * FROM companies WHERE ticker LIKE ? OR name LIKE ? ORDER BY is_seed_data DESC, ticker ASC",
            (query, query)
        ).fetchall()
    else:
        rows = conn.execute("SELECT * FROM companies ORDER BY is_seed_data DESC, ticker ASC").fetchall()
    conn.close()

    return [dict(row) for row in rows]

@router.get("/{ticker}")
def get_company(ticker: str):
    """Get single company profile by ticker."""
    conn = get_db_connection()
    row = conn.execute("SELECT * FROM companies WHERE ticker = ?", (ticker.upper(),)).fetchone()
    conn.close()

    if not row:
        raise HTTPException(status_code=404, detail=f"Company with ticker {ticker} not found in local cache.")

    return dict(row)

import { spawn } from "child_process";
import path from "path";
import { fileURLToPath } from "url";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const rootDir = path.resolve(__dirname, "..");

console.log("🚀 Starting BörsTerminal Development Suite...");

// 1. Start Python FastAPI Sidecar
console.log("🐍 Launching Python Sidecar (FastAPI on port 8000)...");
const sidecar = spawn(
  "python3",
  ["-m", "uvicorn", "app.main:app", "--app-dir", "src-sidecar", "--reload", "--port", "8000"],
  { cwd: rootDir, stdio: "inherit", shell: true }
);

// 2. Start Vite Frontend
console.log("⚡ Launching Vite Dev Server (port 1420)...");
const vite = spawn("npx", ["vite"], { cwd: rootDir, stdio: "inherit", shell: true });

// Handle shutdown cleanly
process.on("SIGINT", () => {
  console.log("\n🛑 Shutting down development processes...");
  sidecar.kill();
  vite.kill();
  process.exit(0);
});

