              activeTab === "BR"
                ? "bg-slate-800 text-white font-bold border border-slate-700"
                : "text-slate-400 hover:text-slate-200 hover:bg-slate-900"
            }`}
          >
            Balansräkning (BR)
          </button>
          <button
            onClick={() => setActiveTab("KA")}
            className={`px-3 py-1 rounded transition-colors ${
              activeTab === "KA"
                ? "bg-slate-800 text-white font-bold border border-slate-700"
                : "text-slate-400 hover:text-slate-200 hover:bg-slate-900"
            }`}
          >
            Kassaflöde (KA)
